import{_ as t,o as r,c as a,a0 as o}from"./chunks/framework.CzVS_xMp.js";const p=JSON.parse('{"title":"Kernel Case Studies (practice)","description":"","frontmatter":{},"headers":[],"relativePath":"gpu/labs/kernels/index.md","filePath":"gpu/labs/kernels/index.md","lastUpdated":1788490169000}'),i={name:"gpu/labs/kernels/index.md"};function n(s,e,l,d,c,h){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="kernel-case-studies-practice" tabindex="-1">Kernel Case Studies (practice) <a class="header-anchor" href="#kernel-case-studies-practice" aria-label="Permalink to &quot;Kernel Case Studies (practice)&quot;">​</a></h1><p>References and backlog for hands-on GPU kernel case studies — the <em>do</em> half of this track. Learn the patterns in [PMPP](../../pmpp/ and [Heterogeneous Systems](../../heterogeneous-systems/, then implement and profile them here with [Profiling](../profiling/.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to &quot;Scope&quot;">​</a></h2><p>Focus on kernels and runtime paths that explain real inference behavior:</p><ul><li>memory coalescing, shared-memory tiling, and occupancy</li><li>reduction, scan, histogram, convolution, and sparse traversal patterns</li><li>GEMM, GEMV, fused softmax, attention, and low-bit GEMM</li><li>Triton, CUTLASS, CUDA C++, and production inference kernels</li><li>Nsight Compute evidence: SM utilization, memory throughput, L2 hit rate, Tensor Core usage, warp stalls</li></ul><p>Related background: [PMPP](../../pmpp/, [Profiling](../profiling/</p><h2 id="resource-index" tabindex="-1">Resource Index <a class="header-anchor" href="#resource-index" aria-label="Permalink to &quot;Resource Index&quot;">​</a></h2><p>Resources here are grouped by media type.</p><h3 id="youtube-lecture-series" tabindex="-1">YouTube / Lecture Series <a class="header-anchor" href="#youtube-lecture-series" aria-label="Permalink to &quot;YouTube / Lecture Series&quot;">​</a></h3><h4 id="selected-kernel-lectures-from-gpu-mode" tabindex="-1">Selected Kernel Lectures from GPU MODE <a class="header-anchor" href="#selected-kernel-lectures-from-gpu-mode" aria-label="Permalink to &quot;Selected Kernel Lectures from GPU MODE&quot;">​</a></h4><ul><li><a href="https://github.com/gpu-mode/lectures" target="_blank" rel="noreferrer">gpu-mode/lectures</a></li><li><a href="https://www.youtube.com/@GPUMODE/videos" target="_blank" rel="noreferrer">GPU MODE YouTube channel</a></li></ul><p>GPU MODE itself is tracked in [GPU MODE](../../gpu-mode/. This section only pulls out the lectures that are directly useful for kernel case studies.</p><p>High-value kernel lectures:</p><table tabindex="0"><thead><tr><th>Topic</th><th>Why it matters</th></tr></thead><tbody><tr><td>Lecture 12: Flash Attention</td><td>attention tiling, SRAM reuse, avoiding materialized attention matrices</td></tr><tr><td>Lecture 14: Practitioner&#39;s Guide to Triton</td><td>practical Triton kernel authoring</td></tr><tr><td>Lecture 15: CUTLASS</td><td>GEMM abstractions, layouts, tiling, Tensor Core usage</td></tr><tr><td>Lecture 18: Fused Kernels</td><td>why fusing removes memory traffic and launch overhead</td></tr><tr><td>Lecture 22: Hacker&#39;s Guide to Speculative Decoding in vLLM</td><td>decode scheduler and verification path intuition</td></tr><tr><td>Lecture 23: Tensor Cores</td><td>why shapes and precision decide kernel paths</td></tr><tr><td>Lecture 29: Triton Internals</td><td>how Triton lowers kernels and where performance comes from</td></tr><tr><td>Lecture 34: Low Bit Triton Kernels</td><td>quantized weights, packing, dequantization, low-bit matmul</td></tr><tr><td>Lecture 36: CUTLASS and FlashAttention 3</td><td>modern attention kernels and CUTLASS/CuTe style</td></tr><tr><td>Lecture 37: Introduction to SASS and GPU Microarchitecture</td><td>what the compiler actually emits</td></tr><tr><td>Lecture 40: FlashInfer</td><td>inference-time attention and serving kernels</td></tr><tr><td>Lecture 57: CuTe</td><td>CUTLASS layout algebra and modern GEMM construction</td></tr></tbody></table><h4 id="parallel-patterns" tabindex="-1">Parallel patterns <a class="header-anchor" href="#parallel-patterns" aria-label="Permalink to &quot;Parallel patterns&quot;">​</a></h4><p>The classic parallel-pattern building blocks (reduction, scan, histogram, convolution, sparse, graph) are covered as a course in [Heterogeneous Systems (Onur Mutlu)](../../heterogeneous-systems/. Each meeting there maps to a case study in the backlog below.</p><h4 id="cuda-crash-course" tabindex="-1">CUDA Crash Course <a class="header-anchor" href="#cuda-crash-course" aria-label="Permalink to &quot;CUDA Crash Course&quot;">​</a></h4><ul><li><a href="https://www.youtube.com/playlist?list=PLxNPSjHT5qvtYRVdNN1yDcdSl39uHV_sU" target="_blank" rel="noreferrer">CUDA Crash Course</a>: useful for basic CUDA kernel patterns.</li></ul><h3 id="articles-worklogs" tabindex="-1">Articles / Worklogs <a class="header-anchor" href="#articles-worklogs" aria-label="Permalink to &quot;Articles / Worklogs&quot;">​</a></h3><ul><li><a href="https://siboehm.com/articles/22/CUDA-MMM" target="_blank" rel="noreferrer">How to Optimize a CUDA Matmul Kernel for cuBLAS-like Performance</a>: the best single worklog for learning matmul optimization by iteration.</li></ul><h3 id="websites-docs" tabindex="-1">Websites / Docs <a class="header-anchor" href="#websites-docs" aria-label="Permalink to &quot;Websites / Docs&quot;">​</a></h3><ul><li><a href="https://triton-lang.org/main/getting-started/tutorials/" target="_blank" rel="noreferrer">Triton tutorials</a>: start with vector add, fused softmax, and matmul.</li><li><a href="https://github.com/NVIDIA/cutlass" target="_blank" rel="noreferrer">NVIDIA CUTLASS documentation</a>: start with the repository docs and examples.</li><li><a href="https://docs.nvidia.com/nsight-compute/" target="_blank" rel="noreferrer">Nsight Compute Documentation</a>: metric definitions and profiling workflow.</li></ul><h3 id="repositories" tabindex="-1">Repositories <a class="header-anchor" href="#repositories" aria-label="Permalink to &quot;Repositories&quot;">​</a></h3><ul><li><a href="https://github.com/CoffeeBeforeArch/cuda_programming" target="_blank" rel="noreferrer">CoffeeBeforeArch CUDA examples</a>: small CUDA kernels for vector add, matmul, reduction, histogram, and convolution.</li><li><a href="https://github.com/NVIDIA/cutlass" target="_blank" rel="noreferrer">CUTLASS</a>: NVIDIA&#39;s template library for high-performance GEMM and related kernels.</li><li><a href="https://github.com/vllm-project/vllm" target="_blank" rel="noreferrer">vLLM</a>: production serving kernels and scheduler/runtime integration.</li><li><a href="https://github.com/Dao-AILab/flash-attention" target="_blank" rel="noreferrer">FlashAttention</a>: attention kernels built around tiling and IO awareness.</li></ul><h3 id="books" tabindex="-1">Books <a class="header-anchor" href="#books" aria-label="Permalink to &quot;Books&quot;">​</a></h3><ul><li>[PMPP](../../pmpp/: background text for basic kernel patterns.</li></ul><h3 id="podcasts-ongoing-feeds" tabindex="-1">Podcasts / Ongoing Feeds <a class="header-anchor" href="#podcasts-ongoing-feeds" aria-label="Permalink to &quot;Podcasts / Ongoing Feeds&quot;">​</a></h3><ul><li>No separate kernel podcast is tracked yet. GPU MODE works as the ongoing feed for modern ML kernel topics.</li></ul><h2 id="topic-sequence" tabindex="-1">Topic Sequence <a class="header-anchor" href="#topic-sequence" aria-label="Permalink to &quot;Topic Sequence&quot;">​</a></h2><ol><li><strong>Vector add:</strong> launch shape, indexing, coalescing, timing.</li><li><strong>Reduction:</strong> synchronization, shared memory, warp-level operations.</li><li><strong>Tiled matmul:</strong> shared-memory tiling, arithmetic intensity, occupancy.</li><li><strong>Fused softmax:</strong> row-wise reductions, numerical stability, memory traffic.</li><li><strong>FlashAttention:</strong> attention without materializing the full score matrix.</li><li><strong>CUTLASS GEMM:</strong> Tensor Core path, layouts, tile hierarchy.</li><li><strong>Triton matmul:</strong> high-level kernel authoring and generated code inspection.</li><li><strong>Low-bit GEMM:</strong> packing, scales, fused dequantization, Marlin/AWQ-style behavior.</li><li><strong>PagedAttention / FlashInfer:</strong> inference-time attention and KV-cache layout.</li><li><strong>Speculative decoding verification path:</strong> scheduler behavior, batch shape, target verification cost.</li></ol><h2 id="case-study-backlog" tabindex="-1">Case Study Backlog <a class="header-anchor" href="#case-study-backlog" aria-label="Permalink to &quot;Case Study Backlog&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Case study</th><th>Core question</th></tr></thead><tbody><tr><td>CUDA vector add</td><td>Are global loads/stores coalesced?</td></tr><tr><td>Reduction</td><td>How does synchronization shape throughput?</td></tr><tr><td>Tiled matmul</td><td>When does arithmetic intensity become high enough?</td></tr><tr><td>GEMV</td><td>Why is batch=1 decode memory-bound or launch-bound?</td></tr><tr><td>Fused softmax</td><td>Why does fusion reduce memory traffic?</td></tr><tr><td>FlashAttention</td><td>How does tiling avoid <code>O(n^2)</code> HBM writes?</td></tr><tr><td>CUTLASS GEMM</td><td>How do Tensor Core layouts and tile shapes work?</td></tr><tr><td>Triton matmul</td><td>How close can a Python-authored kernel get?</td></tr><tr><td>AWQ Marlin</td><td>Why does fused dequantization matter?</td></tr><tr><td>vLLM PagedAttention</td><td>How does KV layout affect serving?</td></tr><tr><td>Speculative verification</td><td>How does one target pass verify K tokens?</td></tr></tbody></table><h2 id="profiling-checklist" tabindex="-1">Profiling Checklist <a class="header-anchor" href="#profiling-checklist" aria-label="Permalink to &quot;Profiling Checklist&quot;">​</a></h2><p>For every kernel case study, record the same small set of facts:</p><table tabindex="0"><thead><tr><th>Item</th><th>Questions</th></tr></thead><tbody><tr><td>Workload shape</td><td>What are M/N/K, batch, sequence length, dtype, and layout?</td></tr><tr><td>Launch shape</td><td>How many blocks, threads, warps, and waves?</td></tr><tr><td>Memory traffic</td><td>Which tensors are read/written? Are accesses coalesced?</td></tr><tr><td>Reuse</td><td>What stays in registers, shared memory, L1, or L2?</td></tr><tr><td>Compute path</td><td>CUDA cores, Tensor Cores, or special instructions?</td></tr><tr><td>Bottleneck</td><td>Launch overhead, memory bandwidth, latency, occupancy, or compute?</td></tr><tr><td>Evidence</td><td>Which Nsight Compute metrics support the conclusion?</td></tr><tr><td>Next experiment</td><td>What single change improves or falsifies the hypothesis?</td></tr></tbody></table>',35)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
